(()=>{'use strict';
const KEY='elhami-journeys-v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), copy=x=>JSON.parse(JSON.stringify(x)), uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2), date=s=>Number.isFinite(Date.parse(s))?new Date(s).toLocaleString('ar-SA',{dateStyle:'medium',timeStyle:'short'}):'تاريخ غير متاح';
const defaults=()=>({schema:1,view:'discover',journey:null,drafts:[],questions:[],activeDraft:null});let state=defaults(), mic=null,micStream=null,micURL=null,micChunks=[],micCancelled=false,micRequest=0,animation=null,lastFocus=null,embedded=window.parent!==window,storageAvailable=true,corruptGuest=false,rawGuest=null;
try{rawGuest=embedded?null:localStorage.getItem(KEY);if(rawGuest!==null){const valid=window.ElhamiJourneySchema.sanitize(JSON.parse(rawGuest));if(valid)state={...defaults(),...valid};else corruptGuest=true;}}catch{storageAvailable=false;if(rawGuest!==null)corruptGuest=true;}
const icons={key:'<svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="38" cy="31" r="18"/><circle cx="38" cy="31" r="7"/><path d="M38 49v37h13v-9H40m0-11h11"/></svg>',notebook:'<svg viewBox="0 0 100 100" aria-hidden="true"><rect x="24" y="13" width="56" height="75" rx="4"/><path d="M33 13v75M17 24h14M17 40h14M17 56h14M17 72h14M44 33h23M44 44h17"/></svg>',pot:'<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M28 22h44l-7 20c22 17 14 44-15 44S13 59 35 42zM37 22v-7h26v7M54 28l-8 15 13 12-10 13 9 15M25 64l-9 12 12 8 8-13z"/></svg>'};
const objects=[{id:'key',name:'مفتاح قديم',hint:'مفتاح معدني قديم',story:'كان يفتح منزلًا هُدم منذ سنوات. احتفظ به صاحبه لأنه آخر ما بقي معه من ذلك المكان.'},{id:'notebook',name:'دفتر فارغ',hint:'دفتر بلا كتابة',story:'لم يُكتب فيه شيء بعد. سيصل إلى شخص يريد كتابة حكايته الأولى، لكنه لم يجد نقطة البداية.'},{id:'pot',name:'قطعة فخار',hint:'قطعة فخار مكسورة',story:'بقايا أول قطعة صنعها شخص بيده. انكسرت قبل أن يهديها، لكنه تعلّم منها كيف يصنع التالية.'}];
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function persist(){if(embedded){if(typeof window.elhamiMarkDirty==='function')window.elhamiMarkDirty();return true;}if(corruptGuest){$('#storage-warning').hidden=false;$('#storage-warning').textContent='تعذر قراءة بيانات سابقة. لم نستبدلها. الحفظ متوقف؛ نزّل النسخة الأصلية من بياناتي ثم اختر المسح صراحة إذا رغبت.';return false;}if(!window.ElhamiJourneySchema.sanitize(state)){$('#storage-warning').hidden=false;$('#storage-warning').textContent='تجاوزت نسخة العمل حدود الحفظ لهذه النسخة. احتفظنا بآخر نسخة صالحة؛ نزّل بيانات العمل من بياناتي قبل المغادرة.';return false;}try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;$('#storage-warning').hidden=false;$('#storage-warning').textContent='لم يُحفظ التعديل في المتصفح. أبقِ الصفحة مفتوحة ونزّل نسخة من بياناتي قبل المغادرة.';}return storageAvailable;}
function setView(v){if(state.view==='world'&&window.ElhamiContextWorkspace?.hasPendingEdits()){if(!confirm('لديك تعديلات في عالمي لم تحفظها. هل تغادر دون حفظها؟'))return;window.ElhamiContextWorkspace.discardPending();}stopRecording(true);clearInterval(animation);state.view=v;persist();render();window.scrollTo({top:0,behavior:'auto'});$('#main').focus({preventScroll:true});}
function modal(html){if(!$('#modal').open)lastFocus=document.activeElement;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
$('.logo').parentElement.onclick=e=>{e.preventDefault();collectForm();setView('discover');};
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>lastFocus?.focus());
function render(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.view));$('#draft-count').textContent=state.drafts.length;const views={discover:discover,world:world,drafts:drafts,journey:journey,idea:idea,reading:reading,group:group,editor:editor,projects:projects};$('#main').innerHTML=(views[state.view]||discover)();bind();}
function discover(){const paths=[['own','01','ما الذي يدور في بالك؟','فكرة، سؤال أو موقف. أعطه مساحة ورتّب ما تريد الاحتفاظ به.','ابدأ من فكرتك'],['reading','02','مرافق القراءة','قف عند معنى، ميّز النص عن فهمك، وارجع إلى المصدر بسؤال أوضح.','افتح دفتر القراءة'],['projects','03','مشاريع معرفية','ادخل من السؤال الذي يشغلك إلى قصة وفكرة ومصدر وتجربة صغيرة.','استكشف المشاريع'],['group','04','المجلس','سؤال مشترك، أصوات مختلفة، وحصيلة تحفظ ما اتفقتم عليه وما بقي مفتوحًا.','جهّز لقاءك']];return `<section class="workspace-welcome"><div><span class="eyebrow">إلهامي · مساحة للمعرفة وأفكارك</span><h1>من أين نبدأ اليوم؟</h1><p class="lead muted">اختر ما يشغلك. لكل باب تجربته، وما تختار الاحتفاظ به يجتمع في عالمك.</p></div><span class="welcome-mark" aria-hidden="true">✦</span></section><section class="entrance-grid" aria-label="مداخل إلهامي الأربعة">${paths.map(([action,n,title,text,cta])=>`<button class="entrance-card" data-action="${action}"><span class="entrance-number">${n}</span><h2>${title}</h2><p>${text}</p><span class="entrance-cta">${cta} <span aria-hidden="true">←</span></span></button>`).join('')}</section><section class="return-strip"><div><span class="eyebrow">لا تبدأ من الصفر كل مرة</span><h2>شيء يستحق أن تعود إليه.</h2><p class="muted">مسوداتك، مذكراتك، والأسئلة التي اخترتها. تراجعها وتعيد ترتيبها بنفسك.</p></div><div class="actions"><button class="secondary" data-nav="world">عالمي</button><button class="quiet" data-nav="drafts">مسوداتي · ${state.drafts.length}</button>${state.project&&(state.project.topic||state.project.choice||state.project.thought||state.project.application)?'<button class="quiet" data-action="projects">أكمل مشروع السلام الداخلي ←</button>':state.journey?'<button class="quiet" data-action="resume">أكمل تجربتي السابقة ←</button>':''}</div></section><details class="capability-note"><summary>كيف تعمل هذه النسخة؟</summary><p>المشاريع والقواعد والمراجع هنا مُعدّة مسبقًا، والبحث يربط الكلمات بالمحتوى المتاح. تستطيع تدوين أفكارك وحفظها وتصديرها. النقاش الحر وفهم التسجيلات يحتاجان ربط الوكيل؛ لا نقدّم ردودًا مُعدّة على أنها فهم آلي لك.</p><p>${embedded?'أنت داخل مساحتك الخاصة. استخدم حفظ التقدم لحفظ نسخة العمل في حسابك.':'أنت في تجربة على هذا الجهاز. يحفظ المتصفح تقدمك؛ للدخول إلى مساحة حسابك استخدم الدخول إلى حسابي.'}</p></details>`;}
function projects(){return window.ElhamiProjects?window.ElhamiProjects.render(state):'<div class="empty"><h1>تعذر تحميل المشاريع</h1><p>أعد تحميل الصفحة. بياناتك السابقة لم تتغير.</p><button data-nav="discover">العودة للبداية</button></div>';}

function start(){if(state.journey&&!confirm('بدء تجربة جديدة؟ ستستبدل التقدم غير المحفوظ كتجربة. المسودات المحفوظة تبقى.'))return;state.journey={id:uid(),version:'objects-1',step:0,first:null,second:null,thought:'',condition:'self',visual:'interactive',updated:new Date().toISOString()};setView('journey');}
function journey(){const j=state.journey;if(!j)return discover();const s=j.step;return `<div class="content-narrow"><div class="section-top"><span class="eyebrow">الأشياء وما وراءها · مشهد ${s+1} من ٥</span><button class="quiet" data-action="save-exit">احفظ التقدم واخرج</button></div><div class="step-line"><div style="width:${(s+1)*20}%"></div></div>${s===0?`<span class="tag">حكاية خيالية أُعدّت للتأمل</span><h1>زيارة إلى ورشة صغيرة.<br>أيّ شيء تأخذه لنفسك؟</h1><p class="lead muted">أنت تزور ورشة صغيرة. يسمح لك صاحبها أن تأخذ شيئًا واحدًا لنفسك من هذا الرف. اختر ما ترغب في الاحتفاظ به؛ بعد ذلك ستعرف حكايته، ثم نغيّر الغرض إلى هدية لشخص آخر. لا نقاط ولا جواب صحيح.</p><p class="small muted">الفخار مكسور أصلًا؛ لن تكسره أو تصلحه في اللعبة. هو أثر محاولة سابقة، مثلما المفتاح أثر مكان والدفتر مساحة لبداية.</p>${objectCards(j.first,'first')}<label for="first-reason">ما الذي جذبك إليه؟ — اختياري</label><textarea id="first-reason" maxlength="3000" placeholder="اكتب سببك الأول قبل معرفة الحكاية، لنقارنه لاحقًا.">${esc(j.firstReason||'')}</textarea><div class="actions"><button data-action="next" ${!j.first?'disabled':''}>لنكتشف ما وراءها ←</button></div>`:s===1?storyReveal(j):s===2?`<span class="tag">كلماتك، لا حكم عليك</span><h1>${j.first===j.second?'بقي الشيء نفسه. هل بقي السبب؟':'تغيّر اختيارك. ما الذي تغيّر معه؟'}</h1><p class="lead">اخترت ${obj(j.first).name} أولًا، ثم ${obj(j.second).name}. لا نستنتج من ذلك صفة فيك. يهمّنا تفسيرك أنت.</p><div class="panel"><span class="origin">سببك الأول، قبل معرفة الحكاية</span><p class="text-preserve">${esc(j.firstReason||'لم تدوّن سببًا أولًا؛ لا نخترع سببًا نيابة عنك.')}</p></div>${j.informed?`<div class="panel"><span class="origin">بعد الحكاية، والشيء ما زال لك</span><p>اخترت ${obj(j.informed).name}.</p><p class="text-preserve">${esc(j.informedReason||'لم تدوّن سببًا في هذه المرحلة.')}</p></div>`:''}<label for="thought">قارن: ماذا تغيّر بعد الحكاية، وماذا تغيّر عندما أصبحت هدية؟ ويمكن ألا يتغيّر اختيارك.</label><textarea id="thought" maxlength="5000" placeholder="قد يكون الغرض الجديد، الحكاية، ذوقي… أو لا أعرف بعد.">${esc(j.thought)}</textarea>${micUI()}<div class="actions"><button data-action="next">افتح زاوية أخرى ←</button><button class="secondary" data-action="clarify">وضّح لي</button><button class="quiet" data-action="back">عودة</button></div>`:s===3?`<span class="tag">وصلات مُعدّة للاستكشاف</span><h1>قد تبقى الأشياء،<br>ويتغيّر إطار النظر.</h1><div class="panel"><span class="origin">صياغة تعليمية مُعدّة، وليست استنتاجًا عن شخصيتك</span><p>يمكن أن نقيّم الشيء بما يذكّرنا به، أو بما يتيحه لنا، أو بما تعلّمناه منه. اختلاف الغرض قد يغيّر ترتيبنا، دون أن يصبح أحد الاختيارات خطأ.</p></div>${knowledgeWindows()}<div class="actions"><button data-action="next">استكشف بصريًا ←</button><button class="secondary" data-action="clarify">وضّح لي</button><button class="quiet" data-action="back">عودة</button></div>`:`<h1>غيّر الغرض، لا الأشياء.</h1><p class="muted">شاهد الشيء الذي اخترته ينتقل من الرف إلى حقيبتك، ثم شاهد هديتك داخل الصندوق. نحن نعرض قرارَيك كما أدخلتهما، ولا نستنتج سببًا لم تقله.</p>${visualUI()}<section class="panel"><h3>ماذا فهمت من المقارنة؟</h3><p>عرفتَ حكاية الأشياء، ثم تغيّر الشخص الذي تختار له. كلاهما قد يؤثر؛ الحركة لا تثبت أيهما السبب. قارن تفسيرَيك بدل أن نستنتج صفة عنك.</p><div class="split"><div><span class="origin">قبل معرفة الحكاية</span><p class="text-preserve">${esc(j.firstReason||'لم تدوّن سببًا أولًا.')}</p></div><div><span class="origin">بعد معرفة الحكاية وتغيّر الغرض</span><p class="text-preserve">${esc(j.thought||'لم تدوّن تفسيرك بعد. يمكنك العودة وكتابته.')}</p></div></div></section><p class="small muted">ما ستحتفظ به: اختياراك، سبباك كما كتبتهما، مشهد يمكنك إعادة تشغيله، وسؤال مفتوح. ستراجعها وتحررها في مسودة، لا تقرير شخصية.</p><div class="actions"><button class="secondary" data-action="journey-idea">هذه تذكّرني بفكرة أريد تطويرها</button><button data-action="journey-draft">حوّل تجربتي إلى مسودة عرض ←</button><button class="secondary" data-action="back">عودة</button></div>`}</div>`;}
const knowledge=[{title:'الأشياء والهوية',question:'هل أحب الشيء، أم القصة التي أرويها عنه؟',text:'يقترح راسل بلك مفهوم الذات الممتدة: قد تدخل بعض مقتنياتنا في الطريقة التي نفهم بها أنفسنا.',example:'في حكايتنا الخيالية، قد يهمّ المفتاح لصاحبه كأثر من حياته، لا كأداة تفتح بابًا. هذا مثال منا، لا نتيجة عن اختيارك.',limit:'إطار بحثي عام، لا اختبار شخصية؛ اختيار مفتاح خيالي لا يكشف هويتك. وقد تحتفظ بشيء لمنفعته فقط.',source:'بلك، 1988 — الملخص المنشور، لا ادعاء قراءة النص الكامل',url:'https://doi.org/10.1086/209154',icon:'key'},{title:'الحكاية والقيمة',question:'متى تضيف الحكاية معنى، ومتى تحجب قيمة الشيء؟',text:'في مشروع Significant Objects، أرفق كتّاب قصصًا خيالية بأشياء مستعملة ثم عُرضت للبيع مع إعلان أن القصص خيالية.',example:'جرّب وصف قطعة الورشة مرة بملامحها، ومرة بحكايتها. ما الذي تضيفه الحكاية لك؟ وما الذي يبقى كما هو؟',limit:'مشروع أدبي وتجربة استكشافية، لا برهان مضبوط على أن كل قصة ترفع كل سعر؛ شهرة الكاتب وطريقة العرض قد تؤثر أيضًا. وقد لا تضيف الحكاية لك قيمة.',source:'Significant Objects — تعريف المشروع وقواعد المرحلة الأولى',url:'https://significantobjects.com/about/',icon:'pot'},{title:'الشيء ليس صورته',question:'ما الذي يوضحه الرسم، وما الذي لا يستطيع أن يمثّله؟',text:'تعرض لوحة ماغريت غليونًا مرسومًا وتقول إنه ليس غليونًا. يشرح متحف LACMA أنها تتحدى مساواة صورة الشيء بالشيء نفسه.',example:'الرسم المتحرك هنا يمثّل الاختيارات التي سجّلتها؛ ليس المفتاح الحقيقي ولا تجربتك كلها. تفسيرك المكتوب يضيف ما لا تقوله الحركة.',limit:'لا يعني ذلك أن الصور بلا فائدة أو أن الحقيقة مستحيلة؛ إنها تذكير بالفارق بين الشيء وتمثيله.',source:'متحف LACMA — ملاحظات العمل وشرح العرض 2021',url:'https://collections.lacma.org/object/31931',icon:'notebook'}];
function knowledgeWindows(){return `<div class="grid">${knowledge.map((k,i)=>`<article class="card"><span class="tag">نافذة معرفية · مصدر وحدود</span><h3>${k.title}</h3><p>${k.question}</p><button class="quiet" data-knowledge="${i}">افتح الفكرة والمثال والرأي المقابل ←</button></article>`).join('')}</div><p class="small muted">الحكاية خيالية. هذه الروابط قراءة مُعدّة بمصادر قابلة للفتح؛ تطبيقها على اختيارك احتمال تناقشه، لا حقيقة عنك.</p>`;}
function openKnowledge(i){const k=knowledge[i];if(!k)return;modal(`<span class="tag">شرح مُعدّ · ليس استنتاجًا آليًا</span><h2>${k.title}</h2><div class="object">${icons[k.icon]}</div><span class="origin">فكرة من المصدر، بصياغة موجزة لا اقتباس</span><p>${k.text}</p><div class="panel"><span class="origin">مثال تطبيقي من إعداد التجربة</span><p>${k.example}</p></div><h3>الحدود والزاوية المقابلة</h3><p>${k.limit}</p><a href="${k.url}" target="_blank" rel="noopener noreferrer">افتح المصدر: ${k.source} ↗</a><div class="actions"><button id="save-knowledge-question">احتفظ بالسؤال في عالمي</button></div>`);$('#save-knowledge-question').onclick=()=>{if(!state.questions.includes(k.question))state.questions.push(k.question);persist();notify('حُفظ السؤال الذي اخترته في عالمي.');};}
function giftStage(j){return typeof j.giftStage==='boolean'?j.giftStage:!!j.second;}
function storyReveal(j){if(!giftStage(j))return `<span class="tag">المعلومة تتغيّر · الغرض ما زال لنفسك</span><h1>الآن تعرف الحكاية.<br>هل تختار شيئًا آخر لنفسك؟</h1><div class="grid objects">${objects.map(o=>`<article class="card"><div class="object">${icons[o.id]}</div><h3>${o.name}</h3><p>${o.story}</p>${j.first===o.id?'<span class="tag">اختيارك قبل الحكاية</span>':''}</article>`).join('')}</div><p>لا يزال الشيء لك، وليس هدية بعد. يمكنك إعادة اختيار الشيء نفسه، أو تغييره، أو تجاوز هذه المقارنة دون تسجيل اختيار.</p>${objectCards(j.informed,'informed',false)}<label for="informed-reason">بعد معرفة الحكاية: ما سببك الآن؟ — اختياري</label><textarea id="informed-reason" maxlength="3000">${esc(j.informedReason||'')}</textarea><div class="actions"><button data-action="next">الآن لنغيّر شرط اللعبة ←</button><button class="quiet" data-action="back">عودة</button></div>`;return `<span class="tag">الغرض يتغيّر · الحكايات نفسها</span><h1>هذه المرة،<br>ستختار لشخص آخر.</h1><div class="panel"><p>ستقدّم الشيء لصديق يبدأ مرحلة جديدة. أنت تعرف الحكايات بالفعل؛ الذي نغيّره الآن هو وجهة الشيء: هدية بدلًا من مقتنى لك.</p><p>اختيارك قبل الحكاية: <b>${obj(j.first).name}</b>. ${j.informed?'بعد الحكاية اخترت لنفسك: <b>'+obj(j.informed).name+'</b>.':'لم تسجّل اختيارًا في المقارنة بعد الحكاية؛ لن نفترضه عنك.'}</p></div>${objectCards(j.second,'second')}<div class="actions"><button data-action="next" ${!j.second?'disabled':''}>قارن ما حدث ←</button><button class="quiet" data-action="back">عودة إلى الحكايات</button></div>`;}
function obj(id){return objects.find(o=>o.id===id)||objects[0];}
function objectCards(selected,field,hint=true){return `<div class="grid objects">${objects.map(o=>`<button class="card card-button ${selected===o.id?'selected':''}" data-choice="${o.id}" data-field="${field}" aria-pressed="${selected===o.id}">${hint?`<div class="object">${icons[o.id]}</div>`:''}<h3>${o.name}</h3>${hint?`<p>${o.hint}</p>`:''}</button>`).join('')}</div>`;}
function micUI(){return `<div class="panel"><div class="actions" style="margin-top:0"><button class="secondary" data-action="record" id="record-button">سجّل فكرتك بصوتك</button><button class="quiet" data-action="cancel-record" id="cancel-record" hidden>إلغاء التسجيل</button></div><p class="small muted" id="record-status">تسجيل محلي للاستماع فقط. لا تفريغ إلى نص الآن؛ اكتب الفكرة التي ترغب بحفظها. الصوت مؤقت ولا يُحفظ مع المسودة.</p><div id="record-playback"></div></div>`;}
function sceneObjectPosition(j,id){const index=objects.findIndex(o=>o.id===id);if(j.condition==='informed'&&j.informed===id)return {x:25,y:66};if(j.condition==='self'&&j.first===id)return {x:25,y:66};if(j.condition==='gift'&&j.second===id)return {x:75,y:66};return {x:20+index*30,y:19};}
function objectScene(j){return `<div class="object-scene" data-condition="${j.condition}" role="img" aria-label="رفّ بثلاثة أشياء، وحقيبة مقتنيات وصندوق هدية. يتحرك اختيارك إلى المكان المرتبط بالغرض."><div class="scene-shelf"><span>رفّ الورشة</span></div><div class="scene-destination scene-self ${['self','informed'].includes(j.condition)?'current':''}"><span>حقيبة مقتنياتك</span></div><div class="scene-destination scene-gift ${j.condition==='gift'?'current':''}"><span>صندوق هدية لصديق</span><i class="gift-ribbon"></i></div>${objects.map(o=>{const pos=sceneObjectPosition(j,o.id);return `<div class="scene-token" data-scene-object="${o.id}" style="left:${pos.x}%;top:${pos.y}%">${icons[o.id]}<b>${o.name}</b></div>`;}).join('')}</div><div class="scene-explanation" aria-live="polite"><span class="tag" id="scene-phase">${j.condition==='self'?'١ · قبل الحكاية، لنفسك':j.condition==='informed'?'٢ · بعد الحكاية، لنفسك':j.condition==='gift'?'٣ · بعد الحكاية، هدية لصديق':'قبل الاختيار · الأشياء على الرف'}</span><p id="scene-cause">${esc(sceneCause(j))}</p></div>`;}
function sceneCause(j){if(j.condition==='equal')return 'الأشياء الثلاثة أمامك كما هي. لم نغيّر شكلها أو قيمتها؛ لم تحدد بعد لمن ستختار.';if(j.condition==='informed')return j.informed?`بعد معرفة الحكاية، اخترت ${obj(j.informed).name} لنفسك. الغرض لم يتغيّر في هذه المقارنة. ${j.informedReason||'لم تدوّن تفسيرك؛ لا نستنتج سببًا من الحركة وحدها.'}`:'لم تسجّل اختيارًا بعد الحكاية؛ لا نعرض اختيارًا مفترضًا.';const chosen=obj(j.condition==='self'?j.first:j.second);return j.condition==='self'?`انتقل ${chosen.name} إلى حقيبتك لأنك اخترته قبل معرفة حكايته. ${j.firstReason||'لم تدوّن سببًا أولًا؛ لا نخترع تفسيرًا.'}`:`انتقل ${chosen.name} إلى صندوق الهدية لأنك اخترته لصديق يبدأ مرحلة جديدة. ${j.first===j.second?'أبقيت الشيء نفسه؛ قد يكون السبب نفسه أو سببًا مختلفًا، وهذا ما توضحه أنت.':'عادت الأشياء غير المختارة إلى الرف، وانتقلت هديتك إلى الصندوق. عرفتَ الحكاية وتغيّر غرض الاختيار. لا تكشف الحركة وحدها أيهما أثّر في قرارك؛ تفسيرك أنت هو المرجع.'}`;}
function visualUI(){const j=state.journey;return `<div class="choice-row" aria-label="نوع العرض">${[['image','صورة'],['motion','مشهد متحرك'],['interactive','مشهد تفاعلي']].map(([id,t])=>`<button data-visual="${id}" aria-pressed="${j.visual===id}">${t}</button>`).join('')}</div><div id="visual-stage" class="story-visual ${j.visual==='image'?'still-scene':''}">${objectScene(j)}</div><p id="visual-description" class="small muted">${visualText()}</p>${j.visual==='interactive'?`<label for="condition">غيّر وجهة الاختيار وشاهد النتيجة</label><select id="condition"><option value="equal" ${j.condition==='equal'?'selected':''}>قبل الاختيار — الأشياء على الرف</option><option value="self" ${j.condition==='self'?'selected':''}>لنفسك — انقل اختياري الأول إلى الحقيبة</option>${j.informed?`<option value="informed" ${j.condition==='informed'?'selected':''}>بعد معرفة الحكاية — اختياري لنفسي</option>`:''}<option value="gift" ${j.condition==='gift'?'selected':''}>هدية — انقل اختياري الثاني إلى الصندوق</option></select><p class="small muted">هذه إعادة عرض لقرارَيك المسجلَين، لا محاكاة لنتائج الحياة ولا توقعًا لما ينبغي أن تختاره.</p>`:j.visual==='motion'?'<div class="actions"><button data-action="animate">أعِد عرض اختياريّ بالحركة</button><button class="secondary" data-action="stop-animation">إيقاف الحركة</button></div><p class="small muted">رفّ الورشة ← اختيارك لنفسك ← هديتك لصديق. تتحرك الأشياء نفسها، لا النصوص. بلا صوت.</p>':'<p class="small muted">لقطة ثابتة لوجهة اختيارك الحالية. غيّر المرحلة في المشهد التفاعلي ثم ارجع إلى الصورة.</p>'}`;}
function visualActive(){return state.journey.condition==='self'?state.journey.first:state.journey.condition==='gift'?state.journey.second:null;}
function visualText(){const j=state.journey;if(j.condition==='informed')return `بعد معرفة الحكاية، اخترت ${obj(j.informed).name} لنفسك.`;return j.condition==='self'?`عندما كان الغرض لك، اخترت ${obj(j.first).name}.`:j.condition==='gift'?`عندما أصبح الغرض هدية، اخترت ${obj(j.second).name}. ${j.first===j.second?'بقاء الاختيار لا يعني بالضرورة بقاء السبب.':'تغيّر الغرض وتغيّر اختيارك المسجّل.'}`:'الأشياء على الرف؛ لا ترتيب مفروض لقيمتها.';}
function idea(){const f=state.idea||{};return `<div class="content-narrow"><span class="eyebrow">من خاطرة إلى مسودة قابلة للبناء</span><h1>ما الذي يدور في بالك؟</h1><p class="lead muted">ابدأ بكلماتك. وسّع الفكرة بالقدر الذي تحتاجه، ثم احفظها في صورة ترجع إليها.</p><p class="small muted">مساحة كتابة موجّهة الآن؛ النقاش مع الوكيل لم يُفعّل بعد.</p>${f.contextLink?`<div class="panel"><span class="tag">امتداد لتجربتك، لا بداية من الصفر</span><p>جئت من اختيار ${obj(f.contextLink.journey.first).name} لنفسك إلى ${obj(f.contextLink.journey.second).name} كهدية. السؤال الذي احتفظت به: ${esc(f.contextLink.question)}</p><p>ما الصلة بفكرتك؟ سمّها أنت؛ لا نفترض أن هذه المقارنة صحيحة أو مناسبة تلقائيًا.</p><div class="actions"><button class="quiet" data-action="context-scene">عُد إلى مشهد التجربة</button><button class="quiet" data-action="remove-context">إزالة الصلة</button></div></div>`:''}<label for="idea-text">الفكرة كما تقولها أنت</label><textarea id="idea-text" maxlength="10000" placeholder="اكتبها دون تنقيح…">${esc(f.text)}</textarea>${micUI()}<details class="idea-workbench"><summary>وسّع الفكرة: لمن تهم، وما الذي قد يتغيّر؟</summary><div class="split"><div><label for="idea-audience">لمن تهم؟</label><input id="idea-audience" maxlength="500" value="${esc(f.audience)}" placeholder="شخص محدد أو فئة، أو: لم أحدد بعد"></div><div><label for="idea-value">ما الذي قد يتغير؟</label><input id="idea-value" maxlength="500" value="${esc(f.value)}" placeholder="الفائدة المحتملة، لا وعدًا مؤكدًا"></div></div><label for="idea-question">ما الذي لا تعرفه بعد؟</label><textarea id="idea-question" maxlength="3000" placeholder="افتراض يحتاج اختبارًا، اعتراض، أو سؤال…">${esc(f.question)}</textarea><label for="idea-next">خطوة صغيرة إن رغبت — اختياري</label><input id="idea-next" maxlength="1000" value="${esc(f.next)}" placeholder="سؤال شخص معني، تجربة نسخة بسيطة…"></details><details class="idea-workbench"><summary>جرّب صياغتين، ثم اختر ما يعبّر عنك</summary><p class="small muted">اكتب البدائل بنفسك، أو رتّب حقولك بقالب معلن. لا يكتب وكيل متصل نيابة عنك. تبقى فكرتك الأصلية أعلاه كما هي.</p><button class="secondary" data-action="idea-templates">رتّب حقولي في قالبين — دون إضافة ادعاءات</button><div class="split"><div><label for="idea-a">الصياغة أ</label><textarea id="idea-a" maxlength="10000">${esc(f.alternativeA)}</textarea><button class="quiet" data-action="adopt-a">اعتمد أ</button><button class="quiet" data-action="merge-a">أضف الجزء المحدّد من أ</button></div><div><label for="idea-b">الصياغة ب</label><textarea id="idea-b" maxlength="10000">${esc(f.alternativeB)}</textarea><button class="quiet" data-action="adopt-b">اعتمد ب</button><button class="quiet" data-action="merge-b">أضف الجزء المحدّد من ب</button></div></div><label for="idea-chosen">الصياغة التي تريد الاحتفاظ بها — عدّلها بحرية</label><textarea id="idea-chosen" maxlength="12000" placeholder="اعتمد بديلًا أو امزج أجزاءه بيدك. التعديل اليدوي هو المعتمد.">${esc(f.chosen)}</textarea><div class="split"><div><label for="idea-objection">اعتراض يستحق الرد</label><textarea id="idea-objection" maxlength="5000" placeholder="اكتبه أنت أو اتركه مفتوحًا؛ لن نخترع اعتراضًا على فكرتك.">${esc(f.objection)}</textarea></div><div><label for="idea-response">ردك أو ما يحتاج مراجعة</label><textarea id="idea-response" maxlength="5000">${esc(f.response)}</textarea></div></div><label for="idea-assumption">افتراض تقوم عليه الفكرة</label><span class="tag">غير متحقق — حتى تضيف دليلًا وتراجعه</span><textarea id="idea-assumption" maxlength="5000" placeholder="مثل: أظن أن المشكلة هي كذا…">${esc(f.assumption)}</textarea><label for="idea-evidence">دليل أو مرجع، وحدود ما يدعمه</label><textarea id="idea-evidence" maxlength="5000" placeholder="اسم المصدر وموضعه أو رابطه، وما الذي يثبته فعلًا. لا تحقق آليًا هنا.">${esc(f.evidence)}</textarea></details><details class="idea-workbench"><summary>إن أردت التجربة في الواقع — اختياري بالكامل</summary><label for="experiment-what">ماذا ستعرض أو تجرّب؟</label><input id="experiment-what" maxlength="2000" value="${esc(f.experiment?.what)}"><label for="experiment-who">مع مَن؟</label><input id="experiment-who" maxlength="1000" value="${esc(f.experiment?.who)}"><label for="experiment-learn">ما الذي تريد معرفته من التجربة؟</label><textarea id="experiment-learn" maxlength="3000">${esc(f.experiment?.learn)}</textarea><label for="experiment-result">ما حدث فعلًا — حين تعود لاحقًا</label><textarea id="experiment-result" maxlength="5000" placeholder="اتركه فارغًا إن لم تجرّب بعد. لا نعدّ الخطة نتيجة.">${esc(f.experiment?.result)}</textarea></details><div class="panel"><span class="origin">قالب عمل مُعدّ</span><p>عدسة التوسيع: ما الاحتمال الآخر؟ عدسة النقد: ما الذي قد يجعلها غير مفيدة؟ عدسة التصفية: ما الجزء الذي تريد الاحتفاظ به؟</p><button class="quiet" data-action="idea-help">وضّح لي بمثال</button></div><div class="actions"><button data-action="idea-draft">رتّب كلماتي في مسودة عرض ←</button><button class="secondary" data-nav="discover">عودة</button></div></div>`;}
function reading(){const r=state.reading||{};return `<div class="content-narrow"><span class="eyebrow">مرافق القراءة · دفترك حول النص</span><h1>اقرأ على مهل.<br>واترك للفكرة أثرًا.</h1><p class="muted">أحضر المعنى الذي توقفت عنده. هنا ترتّب فهمك، وتسجّل السؤال الذي تعود به إلى النص.</p><label for="read-title">ما الذي تقرأه؟</label><input id="read-title" maxlength="300" value="${esc(r.title)}" placeholder="اسم كتاب، مقال، أو مادة مسموعة"><label for="read-excerpt">المقطع الذي تريد الوقوف عنده</label><textarea id="read-excerpt" maxlength="3000" placeholder="أضف مقطعًا قصيرًا مسموحًا لك باستخدامه…">${esc(r.excerpt)}</textarea>${micUI()}<details class="idea-workbench"><summary>أضف مرجع المقطع ونطاق القراءة</summary><label for="read-location">الطبعة والصفحة أو موضع المقطع</label><input id="read-location" maxlength="500" value="${esc(r.location)}" placeholder="إن لم تعرف، اتركه غير محدد"><label for="read-scope">ما النطاق الذي تريد الوقوف عنده؟</label><input id="read-scope" maxlength="1000" value="${esc(r.scope)}" placeholder="مثل: الفصل الأول، أو الدقائق ١٠–٢٠"><label for="read-source">رابط المصدر — اختياري</label><input id="read-source" type="url" dir="ltr" maxlength="2000" value="${esc(r.sourceUrl)}" placeholder="https://"><p class="small muted">المقطع والموضع من إدخالك. لا نجلب الكتاب أو نتحقق من الطبعة والصفحة تلقائيًا.</p></details><details class="idea-workbench" open><summary>فهمك والسؤال الذي يبقى معك</summary><label for="read-understanding">كيف فهمته أنت؟</label><textarea id="read-understanding" maxlength="5000" placeholder="بكلماتك، لا يلزم أن يكون مكتملًا…">${esc(r.understanding)}</textarea><label for="read-other">قراءة أخرى ممكنة — إن وجدت</label><textarea id="read-other" maxlength="3000" placeholder="قد يكون فهمك الأول مناسبًا. لا يلزم اختراع اعتراض.">${esc(r.other)}</textarea><label for="read-question">سؤال أعود به إلى النص</label><input id="read-question" maxlength="1000" value="${esc(r.question)}"></details><div class="panel"><h3>عد إلى كلمة واحدة.</h3><p>أي عبارة في المقطع تدعم فهمك؟ وما الذي أضفته أنت من تجربتك؟ احتفظ بالفرق بينهما.</p><span class="small muted">سؤال مُعدّ للتأمل. المناقشة الحرة مع الوكيل لم تُفعّل بعد.</span></div><div class="actions"><button data-action="reading-draft">احفظ أثر القراءة في مسودة ←</button><button class="secondary" data-nav="discover">عودة</button></div></div>`;}

function group(){const g=state.group||{topic:'ما الذي يعطي الأشياء قيمتها؟',entries:[],revealed:false};state.group=g;return `<div class="content-narrow"><span class="tag">تمرين على جهاز واحد · ليس لقاءً متصلًا</span><h1>نتشارك السؤال،<br>ولا نلزم بعضنا بالإجابة.</h1><p class="muted">اكتبوا رؤاكم بالتناوب، ثم اكشفوا ما بينها من اتفاق واختلاف. هذا المجلس يعمل على جهاز واحد الآن.</p><details class="capability-note"><summary>قبل أن تمرّر الجهاز: الخصوصية</summary><p>إخفاء المداخلات هنا بصري فقط، وليس سرية تقنية. لا تُدخل معلومات خاصة. لا نسحب الذكريات والمسودات إلى المجلس، لكن من يمسك الجهاز يستطيع الانتقال إلى أقسام الحساب الأخرى. اللقاء المتصل ودعوات المشاركين لم تُفعّل بعد.</p></details><label for="group-topic">السؤال أو المادة المشتركة</label><input id="group-topic" maxlength="500" value="${esc(g.topic)}">${!g.revealed?`<div class="panel"><p>عدد المداخلات المكتوبة: <strong>${g.entries.length}</strong></p><label for="group-name">اسم مختصر أو مستعار</label><input id="group-name" maxlength="60" value="${esc(g.pending?.name)}"><label for="group-kind">كيف تصنّف مداخلتك؟</label><select id="group-kind">${[['claim','رأي أو ادعاء'],['evidence','دليل أعرضه — يحتاج مراجعة'],['objection','اعتراض'],['question','سؤال']].map(([id,t])=>`<option value="${id}" ${g.pending?.kind===id?'selected':''}>${t}</option>`).join('')}</select><label for="group-view">رأيك، ودليلك إن وجد</label><textarea id="group-view" maxlength="3000">${esc(g.pending?.text)}</textarea>${micUI()}<div class="actions"><button data-action="group-add">أضف مداخلتي وأخفها</button><button class="secondary" data-action="group-reveal" ${g.entries.length<2?'disabled':''}>اكشف الآراء (${g.entries.length})</button></div></div>`:`<div class="deck">${g.entries.map((e,i)=>`<article class="card"><span class="origin">مداخلة ${i+1} · صحّح النسبة أو الكلمات بموافقة صاحبها</span><label for="group-edit-name-${i}">الاسم</label><input id="group-edit-name-${i}" data-group-edit-name="${i}" maxlength="60" value="${esc(e.name)}"><label for="group-edit-text-${i}">المداخلة</label><textarea id="group-edit-text-${i}" data-group-edit-text="${i}" maxlength="3000">${esc(e.text)}</textarea><label for="group-edit-kind-${i}">نوع المداخلة</label><select id="group-edit-kind-${i}" data-group-edit-kind="${i}">${[['claim','رأي أو ادعاء'],['evidence','دليل عرضه المشارك — لم يتحقق منه الموقع'],['objection','اعتراض'],['question','سؤال']].map(([id,t])=>`<option value="${id}" ${(e.kind||'claim')===id?'selected':''}>${t}</option>`).join('')}</select>${e.original?`<details><summary>النسبة والكلمات قبل أول تصحيح</summary><p class="text-preserve">${esc(e.original.name)}: ${esc(e.original.text)}</p></details>`:''}</article>`).join('')}</div><div class="panel"><h3>بدّلوا المواقع</h3><p>اختر رأيًا ليس رأيك. ما أقوى حجة يمكن أن تدعم صاحبه؟ وما السؤال الذي تحتاجون الرجوع إلى المصدر لحسمه؟</p></div><label for="group-open">موضع اختلاف أو سؤال لا يزال مفتوحًا</label><textarea id="group-open" maxlength="5000">${esc(g.open)}</textarea><div class="actions"><button data-action="group-draft">احفظ حصيلة الطاولة كمسودة ←</button><button class="secondary" data-action="group-hide">إخفاء الآراء</button></div>`}<div class="actions"><button class="quiet" data-action="group-reset">ابدأ طاولة جديدة</button><button class="quiet" data-nav="discover">عودة</button></div></div>`;}
function makeDraft(title,kind,slides,original){title=title.slice(0,200);const d={id:uid(),title,kind,created:new Date().toISOString(),updated:new Date().toISOString(),slides:slides.map(([title,body,origin])=>({id:uid(),title,body,origin,basis:{text:body,origin}})),original,versions:[],sourceStatus:'المدخلات من المستخدم؛ لم تُتحقق المصادر آليًا.'};state.drafts.push(d);state.activeDraft=d.id;setView('editor');notify('أُنشئت مسودة قابلة للتحرير؛ لم يحللها وكيل متصل.');}
function currentDraft(){return state.drafts.find(d=>d.id===state.activeDraft);}
function editor(){const d=currentDraft();if(!d)return drafts();return `<div class="content-narrow"><div class="section-top"><span class="tag">مسودة · ${esc(d.kind)}</span><button class="quiet" data-nav="drafts">كل المسودات ←</button></div><label for="draft-title">عنوان العرض</label><input id="draft-title" value="${esc(d.title)}" maxlength="200"><p class="small muted">التعديلات تبقى في نسخة العمل. «احفظ في المسودات» يضيف إصدارًا مستقلًا دون مسح السابق.</p><div class="actions"><button data-action="save-draft">احفظ في المسودات</button><button class="secondary" data-action="present">عرض المسودة</button><button class="secondary" data-action="draft-visual">استكشف بصريًا</button><button class="secondary" data-action="provenance">كيف تكوّن هذا العرض؟</button><button class="secondary" data-action="export-draft">تنزيل نص العرض</button><button class="secondary" data-action="print">ملف بهوية إلهامي / PDF</button><button class="quiet" data-action="share-draft">مشاركة هذه المسودة</button></div><div class="version-strip"><span class="small">الإصدارات المحفوظة:</span>${d.versions.length?d.versions.map((v,i)=>`<button class="quiet" data-version="${i}">V${i+1} · ${date(v.at)}</button>`).join(''):'<span class="muted small">لا يوجد إصدار محفوظ بعد</span>'}</div><div class="deck">${d.slides.map((s,i)=>`<article class="slide"><span class="origin">${esc(s.origin)} · بطاقة ${i+1}</span><button class="quiet card-origin" data-card-origin="${esc(s.id)}">كيف تكوّنت هذه البطاقة؟</button><div class="slide-head"><input aria-label="عنوان البطاقة ${i+1}" data-slide-title="${esc(s.id)}" maxlength="200" value="${esc(s.title)}"><div class="slide-tools"><button class="quiet" data-move="${esc(s.id)}" data-direction="-1" ${i===0?'disabled':''} aria-label="نقل البطاقة ${i+1} للأعلى">↑</button><button class="quiet" data-move="${esc(s.id)}" data-direction="1" ${i===d.slides.length-1?'disabled':''} aria-label="نقل البطاقة ${i+1} للأسفل">↓</button></div></div><textarea aria-label="نص البطاقة ${i+1}" data-slide-body="${esc(s.id)}" maxlength="12000">${esc(s.body)}</textarea></article>`).join('')}</div><div class="actions"><button class="secondary" data-action="add-slide">أضف بطاقة</button><button data-action="save-draft">احفظ في المسودات</button></div></div>`;}
function drafts(){return `<div class="section-top"><div><span class="eyebrow">أفكارك في صورة قابلة للعودة</span><h1>مسوداتي</h1></div><div class="actions"><button class="secondary" data-action="own">فكرة جديدة +</button><button class="quiet" data-action="new-note">مذكرة جديدة +</button></div></div>${!state.drafts.length?'<div class="empty"><h2>ليس عليك أن تصل لفكرة مكتملة.</h2><p>ابدأ بفكرة أو قراءة أو مشروع. ستجد هنا الكلمات التي اخترت الاحتفاظ بها.</p><button data-nav="discover">اختر البداية</button></div>':`<div class="grid">${state.drafts.slice().reverse().map(d=>`<article class="card"><span class="tag">${esc(d.kind)}</span><h3>${esc(d.title)}</h3><p>${d.slides.length} بطاقات · ${d.versions.length} إصدارات</p><p class="small">آخر تعديل ${date(d.updated)}</p><div class="actions"><button data-open-draft="${esc(d.id)}">افتح المسودة</button><button class="quiet danger" data-delete-draft="${esc(d.id)}">حذف</button></div></article>`).join('')}</div>`}`;}
function world(){return `<div class="section-top"><div><span class="eyebrow">أثر تختاره أنت، لا ملف لشخصيتك</span><h1>عالمي</h1></div></div><div class="split"><section><h2>أكمل من حيث توقفت</h2>${state.project&&(state.project.topic||state.project.choice||state.project.thought||state.project.application)?`<article class="card"><span class="tag">مشروع السلام الداخلي</span><h3>أكمل من موضعك</h3><p>أسئلتك واختياراتك كما سجّلتها، دون تفسير نفسي مفروض.</p><button data-action="projects">عُد إلى المشروع ←</button></article>`:''}${state.journey?`<article class="card"><span class="tag">الأشياء وما وراءها</span><h3>المشهد ${state.journey.step+1} من ٥</h3><p>نحفظ موضعك واختياراتك. يمكنك العودة أو بدء تجربة جديدة بشروطها المعلنة.</p><button data-action="resume">أكمل التجربة ←</button></article>`:'<p class="muted">تجربتك الأولى تنتظرك في اكتشف.</p>'}<h2>أسئلة احتفظت بها</h2>${state.questions.length?state.questions.map((q,i)=>`<article class="panel"><p>${esc(q)}</p><button class="quiet" data-remove-question="${i}">إزالة من عالمي</button></article>`).join(''):'<p class="muted">اختر ما يهمك من الأسئلة أثناء التجربة.</p>'}</section><section><h2>ما تكوّن بيدك</h2><div class="timeline">${state.drafts.length?state.drafts.slice().reverse().map(d=>`<article><span class="small muted">${date(d.updated)}</span><h3>${esc(d.title)}</h3><p class="muted">${d.versions.length>1?'لديك أكثر من إصدار؛ راجع ما غيّرته دون افتراض أن التغيير تحسّن تلقائيًا.':'فكرة قابلة للعودة والبناء، لا درجة لقياسك.'}</p><button class="quiet" data-open-draft="${esc(d.id)}">عُد إليها ←</button></article>`).join(''):'<p class="muted">ستظهر هنا مسوداتك وإصداراتها، لا تقييم أو درجة نمو.</p>'}</div></section></div>${window.ElhamiContextWorkspace?.render(state)||''}`;}
function collectForm(){if(state.view==='journey'&&$('#informed-reason'))state.journey.informedReason=$('#informed-reason').value;if(state.view==='journey'&&$('#first-reason'))state.journey.firstReason=$('#first-reason').value;if(state.view==='journey'&&$('#thought'))state.journey.thought=$('#thought').value;if(state.view==='idea')state.idea={...state.idea,text:$('#idea-text').value,audience:$('#idea-audience').value,value:$('#idea-value').value,question:$('#idea-question').value,next:$('#idea-next').value,alternativeA:$('#idea-a').value,alternativeB:$('#idea-b').value,chosen:$('#idea-chosen').value,objection:$('#idea-objection').value,response:$('#idea-response').value,assumption:$('#idea-assumption').value,evidence:$('#idea-evidence').value,experiment:{what:$('#experiment-what').value,who:$('#experiment-who').value,learn:$('#experiment-learn').value,result:$('#experiment-result').value}};if(state.view==='reading')state.reading=Object.fromEntries(['title','location','excerpt','understanding','other','question','scope'].map(k=>[k,$('#read-'+k).value]).concat([['sourceUrl',$('#read-source').value]]));if(state.view==='group'){state.group.topic=$('#group-topic').value;if($('#group-name'))state.group.pending={name:$('#group-name').value,text:$('#group-view').value,kind:$('#group-kind').value};if(state.group.revealed)state.group.entries.forEach((entry,i)=>{const name=$('#group-edit-name-'+i)?.value,text=$('#group-edit-text-'+i)?.value,kind=$('#group-edit-kind-'+i)?.value;if(name!==undefined&&text!==undefined&&(name!==entry.name||text!==entry.text||kind!==(entry.kind||'claim'))){entry.original=entry.original||{name:entry.name,text:entry.text,kind:entry.kind||'claim'};Object.assign(entry,{name,text,kind});}});if($('#group-open'))state.group.open=$('#group-open').value;}if(state.view==='editor'){const d=currentDraft();if(d){const before=JSON.stringify({title:d.title,slides:d.slides});d.title=$('#draft-title').value;d.slides.forEach(s=>{s.title=$(`[data-slide-title="${esc(s.id)}"]`).value;s.body=$(`[data-slide-body="${esc(s.id)}"]`).value;});if(before!==JSON.stringify({title:d.title,slides:d.slides}))d.updated=new Date().toISOString();}}persist();}
function bind(){if(state.view==='projects')window.ElhamiProjects?.bind({state,persist,render,notify,setView,modal,isPrivate:embedded,savePrivate:embedded?requestAccountSave:null,createDraft:(title,kind,original,slides)=>makeDraft(title,kind,slides.map(s=>[s.title,s.body,s.origin]),original)});document.querySelectorAll('[data-knowledge]').forEach(b=>b.onclick=()=>openKnowledge(+b.dataset.knowledge));if(state.view==='world')window.ElhamiContextWorkspace?.bind({state,persist,render,notify,isPrivate:embedded,savePrivate:requestAccountSave,openDraft:id=>{state.activeDraft=id;setView('editor');}});document.querySelectorAll('[data-card-origin]').forEach(b=>b.onclick=()=>{collectForm();const d=currentDraft(),card=d?.slides.find(s=>s.id===b.dataset.cardOrigin);if(!card)return;modal(`<h2>${esc(card.title)}</h2><span class="origin">${esc(card.origin)}</span>${card.basis?`<h3>النص عند إنشاء البطاقة</h3><p class="text-preserve">${esc(card.basis.text)}</p><p class="small muted">تعديلاتك الحالية لا تغيّر هذا الأصل. هذه نسبة إلى المدخلات أو القالب المعلن، وليست ادعاء بتحقق مستقل.</p>`:'<p>هذه بطاقة قديمة لا تحتوي لقطة مستقلة عند إنشائها؛ لا نخترع لها أصلًا. راجع المدخلات الأصلية للعرض وإصداراته المحفوظة.</p>'}`);});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{collectForm();setView(b.dataset.nav);});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state.journey[b.dataset.field]=b.dataset.choice;persist();render();});document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{if(!state.questions.includes(b.dataset.question))state.questions.push(b.dataset.question);persist();notify('حُفظ السؤال في عالمي.');});document.querySelectorAll('[data-remove-question]').forEach(b=>b.onclick=()=>{if(window.ElhamiContextWorkspace?.hasPendingEdits()){if(!confirm('لديك تعديلات لم تحفظها في عالمي. إزالة السؤال ستغلق النموذج دون حفظ؛ هل تتابع؟'))return;window.ElhamiContextWorkspace.discardPending();}state.questions.splice(+b.dataset.removeQuestion,1);persist();render();});document.querySelectorAll('[data-visual]').forEach(b=>b.onclick=()=>{clearInterval(animation);state.journey.visual=b.dataset.visual;persist();render();});$('#condition')?.addEventListener('change',e=>{clearInterval(animation);state.journey.condition=e.target.value;persist();paintVisual();});document.querySelectorAll('[data-open-draft]').forEach(b=>b.onclick=()=>{state.activeDraft=b.dataset.openDraft;setView('editor');});document.querySelectorAll('[data-delete-draft]').forEach(b=>b.onclick=()=>{if(confirm('حذف هذه المسودة وجميع إصداراتها؟ لا يمكن التراجع.')){state.drafts=state.drafts.filter(d=>d.id!==b.dataset.deleteDraft);persist();render();}});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{collectForm();const d=currentDraft(),i=d.slides.findIndex(s=>s.id===b.dataset.move),n=i+ +b.dataset.direction;[d.slides[i],d.slides[n]]=[d.slides[n],d.slides[i]];persist();render();});document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>showVersion(+b.dataset.version));$('#main').querySelectorAll('[data-group-edit-kind]').forEach(e=>e.addEventListener('change',collectForm));$('#main').querySelectorAll('input,textarea').forEach(e=>e.addEventListener('input',()=>{collectForm();}));}
async function act(a){if(!['record','cancel-record','animate'].includes(a))collectForm();switch(a){case'save-exit':setView('discover');if(embedded)requestAccountSave();break;case'start':start();break;case'resume':setView('journey');break;case'own':setView('idea');break;case'projects':setView('projects');break;case'new-note':makeDraft('مذكرة جديدة','مذكرة',[['ما أريد الاحتفاظ به','','كتابة المستخدم']],{});break;case'reading':setView('reading');break;case'group':setView('group');break;case'next':if(state.journey.step===1&&!giftStage(state.journey)){state.journey.giftStage=true;setView('journey');break;}if(state.journey.step===0&&!state.journey.first||state.journey.step===1&&!state.journey.second)return;state.journey.step=Math.min(4,state.journey.step+1);setView('journey');break;case'back':if(state.journey.step===1&&giftStage(state.journey)){state.journey.giftStage=false;setView('journey');break;}state.journey.step=Math.max(0,state.journey.step-1);setView('journey');break;case'clarify':modal('<span class="tag">توضيح مُعدّ</span><h2>ماذا يحدث في هذه القصة؟</h2><p>أنت لا تكسر الفخار، ولا نختبر شخصيتك. تزور ورشة وتختار شيئًا لنفسك، ثم تختار هدية لصديق من الأشياء نفسها. نريد أن تلاحظ: هل تغيّر اختيارك عندما تغيّر الغرض؟ ولماذا، بكلماتك أنت؟</p><p>قد تختار مفتاحًا لنفسك لأنه يذكّرك بمكان. لكنك تختار دفترًا هديةً لأن الشخص الآخر يريد الكتابة. هذا مثال على أثر الغرض، لا تفسير لاختيارك أنت.</p><p>ويمكن أيضًا أن تحتفظ بنفس الاختيار لسبب جديد. اكتب السبب الذي تقصده، أو اتركه سؤالًا مفتوحًا.</p>');break;case'idea-help':modal('<span class="tag">مثال توضيحي، لا تحليل لفكرتك</span><h2>من جملة واسعة إلى سؤال قابل للاختبار</h2><p>«أريد نادي قراءة» ← لمن؟ «لمن يبدأ القراءة ويتركها سريعًا». ما الفائدة المحتملة؟ «لقاء قصير يساعده على إكمال فصل». ما الافتراض؟ «أن المشكلة غياب الرفقة، لا ضيق الوقت». ما الاختبار؟ «أسأل ثلاثة أشخاص عن آخر مرة توقفوا فيها».</p><p>خذ البنية فقط. ليس مطلوبًا أن تحوّل كل فكرة إلى مشروع أو مهمة.</p>');break;case'journey-idea':state.idea={...(state.idea||{}),contextLink:{journey:copy(state.journey),question:state.questions.at(-1)||'كيف تؤثر معرفة الحكاية والغرض في تقدير الفكرة؟'}};setView('idea');break;case'context-scene':showSavedStory({original:state.idea.contextLink.journey});break;case'remove-context':if(confirm('إزالة الصلة بهذه التجربة من الفكرة؟ لن نحذف نص الفكرة أو التجربة.')){delete state.idea.contextLink;persist();render();}break;case'journey-draft':{const j=state.journey;makeDraft('ما الذي تغيّر حين تغيّر الغرض؟','تجربة تفاعلية',[['نقطة البداية',`اخترت ${obj(j.first).name} لنفسي، ثم ${obj(j.second).name} كهدية لشخص يبدأ مرحلة جديدة.`,'اختيارات سجلها المستخدم'],...(j.informed?[['اختياري بعد معرفة الحكاية',`اخترت ${obj(j.informed).name} لنفسي.\n${j.informedReason||'لم أدوّن السبب.'}`,'اختيار المستخدم بعد كشف الحكاية وقبل تغيير الغرض']]:[]),['سببي الأول',j.firstReason||'لم أدوّن سببًا أولًا.','نص المستخدم قبل معرفة الحكاية'],['كلماتي بعد تغيّر السياق',j.thought||'لم أكتب تفسيري بعد.','نص المستخدم — قابل للتحرير'],['الزاوية التي اختبرتها','هل جاءت القيمة من الشيء، أم حكايته، أم الغرض الذي اخترته من أجله؟','سؤال مُعدّ للتجربة، ليس اقتباسًا'],['المشهد البصري',visualText(),'تمثيل مبسّط لاختيارات المستخدم'],['ما يزال مفتوحًا',state.questions.join('\n')||'ما المعلومة التي قد تغيّر اختياري مرة أخرى؟','أسئلة اختيرت أو سؤال افتتاحي مُعدّ']],copy(j));break;}case'idea-templates':{const f=state.idea;if(!f.text.trim()){notify('اكتب فكرتك الأصلية أولًا.');break;}if([f.text,f.audience,f.value].filter(Boolean).join('\n').length>9800){notify('النص طويل لترتيبه في قالبين دون قص؛ اكتب البديلين يدويًا أو اختصرهما بنفسك.');break;}if(f.alternativeA&&f.alternativeB){notify('البديلان موجودان؛ عدّلهما يدويًا حتى لا نستبدل عملك.');break;}f.alternativeA=f.alternativeA||[f.text,f.audience?'لمن: '+f.audience:'',f.value?'الفائدة المقصودة: '+f.value:''].filter(Boolean).join('\n');f.alternativeB=f.alternativeB||[f.value?'الفائدة المقصودة: '+f.value:'',f.audience?'لمن: '+f.audience:'',f.text].filter(Boolean).join('\n');persist();render();notify('رُتّبت كلماتك في قالبين؛ لم تُضف ادعاءات جديدة.');break;}case'adopt-a':case'adopt-b':{const f=state.idea,value=a==='adopt-a'?f.alternativeA:f.alternativeB;if(!value){notify('اكتب الصياغة أولًا.');break;}if(f.chosen&&f.chosen!==value&&!confirm('استبدال الصياغة المعتمدة بهذا البديل؟ ستبقى الفكرتان البديلتان والأصل محفوظة في النموذج.'))break;f.chosen=value;persist();render();break;}case'merge-a':case'merge-b':{const input=$(a==='merge-a'?'#idea-a':'#idea-b'),piece=input.value.slice(input.selectionStart,input.selectionEnd);if(!piece.trim()){notify('حدّد جزءًا من النص داخل البديل أولًا، ثم اضغط إضافة الجزء المحدّد.');break;}state.idea.chosen=[state.idea.chosen,piece].filter(Boolean).join('\n');if(state.idea.chosen.length>12000){state.idea.chosen=state.idea.chosen.slice(0,-piece.length-1);notify('لم يُضف الجزء؛ الصياغة ستتجاوز حد الحفظ.');break;}persist();render();break;}case'idea-draft':{const f=state.idea;if(!f.text.trim()){notify('اكتب فكرتك أولًا، ولو جملة واحدة.');$('#idea-text').focus();return;}makeDraft(f.text.trim().slice(0,65),'فكرة',[['الفكرة كما بدأت',f.text,'نص المستخدم الأصلي'],...(f.chosen?[['الصياغة المعتمدة',f.chosen,'اختيار وتحرير المستخدم؛ البدائل والأصل محفوظة']]:[]),...(f.alternativeA?[['الصياغة أ',f.alternativeA,'نص المستخدم أو قالب يعيد ترتيب حقوله دون ادعاءات إضافية']]:[]),...(f.alternativeB?[['الصياغة ب',f.alternativeB,'نص المستخدم أو قالب يعيد ترتيب حقوله دون ادعاءات إضافية']]:[]),['لمن وما القيمة المحتملة',`لمن: ${f.audience||'لم أحدد بعد'}\nما قد يتغيّر: ${f.value||'لم أحدد بعد'}`,'ترتيب حقول المستخدم — لا تحليل آلي'],...(f.objection||f.response?[['اعتراض وردّ',`الاعتراض:\n${f.objection||'لم يُكتب.'}\n\nردّي أو ما أراجعه:\n${f.response||'لم يُكتب.'}`,'كتابة المستخدم، لا نقد آلي']]:[]),...(f.assumption?[['افتراض غير متحقق',f.assumption,'افتراض المستخدم؛ لا نعدّه حقيقة مثبتة']]:[]),['ما يحتاج اختبارًا',f.question||'ما الافتراض الذي تقوم عليه الفكرة؟','سؤال المستخدم أو قالب افتتاحي'],['خطوة ممكنة',f.next||'لم أختر خطوة الآن، وهذا مقبول.','اختياري، لا التزام مفروض'],...(f.contextLink?[['السياق الذي بدأت منه',`بعد تجربة الأشياء، احتفظت بالسؤال: ${f.contextLink.question}\nهذه صلة اخترتها أنا؛ ليست دليلًا على صحة فكرتي.`,'صلة اختارها المستخدم؛ أصل التجربة محفوظ مع المسودة']]:[]),...(f.experiment&&Object.values(f.experiment).some(Boolean)?[['تجربة اختيارية ونتيجتها',`ما أجرّبه: ${f.experiment.what||'لم أحدد.'}\nمع مَن: ${f.experiment.who||'لم أحدد.'}\nما أريد معرفته: ${f.experiment.learn||'لم أحدد.'}\nما حدث فعلًا: ${f.experiment.result||'لم تُسجّل نتيجة؛ الخطة ليست إنجازًا.'}`,'خطة ونتيجة يدوّنهما المستخدم، دون إثبات آلي للتنفيذ']]:[]),['الأدلة والمراجع',f.evidence||'لم تُضف أدلة بعد. دوّن مصدرًا قابلًا للرجوع إليه، وافصل الدليل عن توقعك.','حقل للمراجعة — لا مصادر مختلقة']],copy(f));break;}case'reading-draft':{const r=state.reading;if(r.sourceUrl&&!/^https?:\/\/[^\s]+$/i.test(r.sourceUrl)){notify('استخدم رابط مصدر يبدأ بـ https:// أو http:// دون مسافات، أو اتركه فارغًا.');return;}if(!r.excerpt.trim()||!r.title.trim()){notify('أضف اسم المادة ومقطعًا قصيرًا أولًا.');return;}makeDraft('قراءة: '+r.title,'قراءة',[['المصدر',`${r.title}\nالموضع: ${r.location||'غير محدد'}\nالنطاق: ${r.scope||'المقطع المدخل فقط'}\nالرابط: ${r.sourceUrl||'لم يُضف رابط'}\nلم يُتحقق من المصدر أو الصفحة آليًا.`,'بيانات أدخلها المستخدم'],['النص الذي توقفت عنده',r.excerpt,'مقطع أدخله المستخدم — يحتاج تحققًا من الأصل'],['فهمي',r.understanding||'لم أكتب فهمي بعد.','قراءة المستخدم، لا قول منسوب للمؤلف'],['قراءة أخرى',r.other||'لم أكتب قراءة بديلة بعد.','احتمال أو اعتراض، لا حقيقة مؤكدة'],['سؤال أعود به',r.question||'أي جزء من النص يدعم فهمي؟','سؤال للمراجعة']],copy(r));break;}case'group-add':{if(state.group.entries.length>=30){notify('هذه الطاولة تستوعب ٣٠ مداخلة في النسخة الحالية. احفظها وابدأ طاولة جديدة.');return;}const name=$('#group-name').value.trim(),text=$('#group-view').value.trim();if(!name||!text){notify('اكتب اسمًا مختصرًا ومداخلة.');return;}state.group.entries.push({name,text,kind:$('#group-kind').value||'claim'});state.group.pending={name:'',text:''};stopRecording(true);persist();render();notify('أُضيفت المداخلة وأُخفيت في الواجهة. مرّر الجهاز.');break;}case'group-reveal':stopRecording(true);state.group.revealed=true;persist();render();break;case'group-hide':state.group.revealed=false;persist();render();break;case'group-reset':if(confirm('بدء طاولة جديدة؟ احفظ حصيلة الطاولة الحالية أولًا إن أردت.')){state.group=null;render();persist();}break;case'group-draft':{const g=state.group;makeDraft(g.topic,'طاولة مشتركة',[['السؤال المشترك',g.topic,'مدخل المشاركين'],...g.entries.map(e=>['صوت '+e.name,e.text,'مداخلة المشارك — '+({claim:'رأي أو ادعاء',evidence:'دليل عرضه المشارك، غير متحقق',objection:'اعتراض',question:'سؤال'}[e.kind]||'غير مصنفة')]),['ما لم نحسمه',g.open||'لم يُدوّن اتفاق أو اختلاف نهائي.','اختلاف محفوظ، لا إجماع مفترض']],copy(g));break;}case'save-draft':{const d=currentDraft();if(accountSaving){notify('الحفظ جارٍ؛ انتظر تأكيده قبل حفظ إصدار آخر.');return;}const last=d.versions.at(-1);if(!last||last.title!==d.title||JSON.stringify(last.slides)!==JSON.stringify(d.slides))d.versions.push({at:new Date().toISOString(),title:d.title,slides:copy(d.slides)});if(embedded){requestAccountSave();notify('جارٍ حفظ الإصدار في مساحتك الخاصة…');}else if(persist())notify(`حُفظ الإصدار V${d.versions.length} على هذا الجهاز.`);render();break;}case'present':presentDraft();break;case'draft-visual':draftVisual();break;case'provenance':{const d=currentDraft();modal(`<h2>كيف تكوّن هذا العرض؟</h2><p>رُتّبت مدخلاتك في قالب واضح. لم تُجرَ قراءة نفسية أو مراجعة آلية للمصادر. وسم كل بطاقة يوضح أصلها؛ تعديلاتك اللاحقة تبقى ملكك.</p><h3>ما بدأتَ به</h3>${originCards(d)}<p>الإصدارات المحفوظة لا تُعدّل عند تعديل نسخة العمل.</p>`);break;}case'add-slide':currentDraft().slides.push({id:uid(),title:'بطاقة جديدة',body:'',origin:'إضافة المستخدم'});persist();render();break;case'export-draft':{const d=currentDraft();download('elhami-draft.txt',d.title+'\n\n'+d.slides.map(s=>s.title+'\n'+s.body+'\n['+s.origin+']').join('\n\n'));break;}case'print':case'share-draft':if(window.ElhamiDraftExport)window.ElhamiDraftExport.open(currentDraft(),{modal,notify});else notify('تعذر تحميل أداة التصدير. أعد تحميل الصفحة.');break;case'record':if(mic?.state==='recording')stopRecording(false);else await startRecording();break;case'cancel-record':stopRecording(true);break;case'animate':animate();break;case'stop-animation':clearInterval(animation);persist();notify('توقفت الحركة عند المشهد الحالي.');break;}}
function originCards(d){const o=d.original||{};let rows=[];if(d.kind==='تجربة تفاعلية')rows=[['اختيارك الأول',obj(o.first).name],['اختيارك بعد تغيّر الغرض',obj(o.second).name],['اختيارك بعد الحكاية وقبل الهدية',o.informed?obj(o.informed).name:'لم تسجّل اختيارًا في هذه المرحلة.'],['سببك بعد الحكاية',o.informedReason],['سببك الأول قبل الحكاية',o.firstReason],['كلماتك عند التأمل',o.thought],['نوع المادة','حكاية خيالية مُعدّة للتجربة، وليست نصًا من كتاب أو اختبارًا نفسيًا.']];else if(d.kind==='فكرة')rows=[['الفكرة بكلماتك الأصلية',o.text],['لمن تهم الفكرة؟',o.audience],['القيمة المحتملة التي كتبتها',o.value],['ما لم تعرفه بعد',o.question],['الصياغة أ',o.alternativeA],['الصياغة ب',o.alternativeB],['الصياغة المعتمدة',o.chosen],['اعتراض كتبته',o.objection],['ردك',o.response],['افتراض غير متحقق',o.assumption],['دليل أدخلته ويحتاج مراجعة',o.evidence],['الخطوة التي اقترحتها',o.next],...(o.contextLink?[['صلة اخترتها بتجربة سابقة',o.contextLink.question],['تفسيرك في تلك التجربة',o.contextLink.journey.thought]]:[]) ];else if(d.kind==='قراءة')rows=[['المصدر الذي أدخلته',o.title],['الطبعة أو موضع المقطع',o.location],['نطاق القراءة المسموح',o.scope],['رابط المصدر من إدخالك',o.sourceUrl],['المقطع كما أدخلته',o.excerpt],['فهمك أنت، لا قول المؤلف',o.understanding],['قراءتك الأخرى أو اعتراضك',o.other],['السؤال الذي تعود به إلى النص',o.question],['حدود التحقق','لم نتحقق آليًا من نسبة المقطع أو الطبعة أو الصفحة. ارجع إلى المصدر عند الاستشهاد.']];else if(d.kind==='طاولة مشتركة')rows=[['السؤال المشترك',o.topic],...(Array.isArray(o.entries)?o.entries.flatMap(e=>[['مداخلة '+e.name,e.text],...(e.original?[['قبل أول تصحيح للنسبة والكلمات',e.original.name+': '+e.original.text]]:[])]):[]),['الاختلاف أو السؤال المفتوح',o.open]];else rows=[['أصل البطاقات','تجد أصل كل بطاقة فوق نصها. هذه مسودة قابلة للتحرير وليست نتيجة تحليل آلي.']];return '<div class="deck">'+rows.map(([label,text])=>`<article class="panel" style="margin:0"><span class="origin">${esc(label)}</span><p class="text-preserve">${esc(text||'لم تُضف إجابة في هذه المرحلة.')}</p></article>`).join('')+'</div>';}
function presentDraft(){const d=currentDraft();let i=0;function paint(){const s=d.slides[i];modal(`<span class="tag">عرض مسودة · <bdi dir="ltr">${i+1} / ${d.slides.length}</bdi></span><h2>${esc(s.title)}</h2><div class="presentation-text text-preserve">${esc(s.body)}</div><p class="origin">${esc(s.origin)}</p><div class="actions"><button id="slide-prev" class="secondary" ${i===0?'disabled':''}>السابق</button><button id="slide-next" ${i===d.slides.length-1?'disabled':''}>التالي ←</button></div><p class="small muted">استخدم سهمي اليمين واليسار للتنقل. العرض لا يغيّر المسودة.</p>`);$('#slide-prev').onclick=()=>{if(i>0){i--;paint();}};$('#slide-next').onclick=()=>{if(i<d.slides.length-1){i++;paint();}};}paint();const keys=e=>{if(e.key==='ArrowLeft'&&i<d.slides.length-1){e.preventDefault();i++;paint();}if(e.key==='ArrowRight'&&i>0){e.preventDefault();i--;paint();}};$('#modal').addEventListener('keydown',keys);$('#modal').addEventListener('close',()=>$('#modal').removeEventListener('keydown',keys),{once:true});}
function draftVisual(){const d=currentDraft();if(d.kind==='تجربة تفاعلية'&&d.original?.first&&d.original?.second){showSavedStory(d);return;}modal(`<h2>استكشف بصريًا</h2><p>هذه المسودة نصّية. المتاح الآن هو تنسيق كلماتك في صورة بطاقات أو عرضها بالتتابع فقط؛ هذا ليس تحويل الفكرة إلى مشهد يشرح معناها. تحويل نص حرّ إلى رسوم توضيحية متحركة غير متاح في هذه النسخة.</p><label for="visual-card-count">عدد البطاقات في الصورة</label><select id="visual-card-count">${[2,3,4].filter(n=>n<=d.slides.length).map(n=>`<option value="${n}">${n} بطاقات</option>`).join('')}</select><div class="actions"><button id="draft-image">صورة قابلة للتنزيل</button><button class="secondary" id="draft-motion">عرض البطاقات بالتتابع — ليس رسمًا توضيحيًا</button></div><div id="draft-visual-output"></div><p class="small muted">المحاكاة التفاعلية متاحة الآن في تجربة الأشياء فقط، حيث القواعد مُعدّة ومعلنة. لا نولّد محاكاة علمية أو فهمًا حرًا من أي نص.</p>`);$('#draft-image').onclick=()=>{clearInterval(animation);const n=+$('#visual-card-count').value||Math.min(3,d.slides.length),ss=d.slides.slice(0,n),svg=makeSVG(d,ss);$('#draft-visual-output').innerHTML='<div class="panel"><h3>صورة البطاقات جاهزة</h3><p>تتضمن العناوين وأول جزء من كل بطاقة، وتحتفظ المسودة بالنص الكامل.</p><button id="download-svg">تنزيل الصورة SVG</button></div>';$('#download-svg').onclick=()=>{const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='elhami-cards.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);};};$('#draft-motion').onclick=()=>{clearInterval(animation);let i=0;const paint=()=>{$('#draft-visual-output').innerHTML=`<article class="panel motion-card"><span class="origin">بطاقة ${i+1} من ${d.slides.length} · عرض حركي مُعدّ</span><h3>${esc(d.slides[i].title)}</h3><p class="text-preserve">${esc(d.slides[i].body)}</p><button id="motion-stop" class="quiet">إيقاف المشهد</button></article>`;$('#motion-stop').onclick=()=>clearInterval(animation);};paint();if(matchMedia('(prefers-reduced-motion: reduce)').matches){notify('عُرضت بطاقة ثابتة وفق إعداد تقليل الحركة. استخدم عرض المسودة للتنقل.');return;}animation=setInterval(()=>{i++;if(i>=d.slides.length){clearInterval(animation);return;}paint();},4500);};$('#modal').addEventListener('close',()=>clearInterval(animation),{once:true});}
function makeSVG(d,slides){const h=150+slides.length*200;return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="${h}" viewBox="0 0 1000 ${h}"><rect width="1000" height="${h}" fill="#f6f2e9"/><text x="940" y="70" text-anchor="end" font-family="Tahoma,Arial" font-size="30" fill="#294759">${esc(d.title.slice(0,65))}</text>${slides.map((s,i)=>{const y=110+i*200;const words=s.body.slice(0,160).split(/\s+/),lines=[];while(words.length){lines.push(words.splice(0,10).join(' '));if(lines.length===3)break;}return `<rect x="40" y="${y}" width="920" height="180" rx="18" fill="#fffdf8" stroke="#c9bea5"/><text x="925" y="${y+40}" text-anchor="end" font-family="Tahoma,Arial" font-size="24" fill="#294759">${esc(s.title.slice(0,60))}</text>${lines.map((l,j)=>`<text x="925" y="${y+78+j*28}" text-anchor="end" font-family="Tahoma,Arial" font-size="18" fill="#526d7a">${esc(l)}</text>`).join('')}<text x="925" y="${y+164}" text-anchor="end" font-family="Tahoma,Arial" font-size="12" fill="#647982">${esc(s.origin.slice(0,100))}</text>`;}).join('')}</svg>`;}
function showVersion(i){collectForm();const d=currentDraft(),v=d.versions[i];modal(`<span class="tag">V${i+1} · قراءة فقط</span><h2>${esc(v.title)}</h2>${v.slides.map(s=>`<h3>${esc(s.title)}</h3><p class="text-preserve">${esc(s.body)}</p>`).join('')}<button id="restore-version">استخدم هذا الإصدار في نسخة العمل</button><p class="small muted">لن يُحذف أي إصدار. تُحفظ نسخة العمل الحالية أولًا كإصدار مستقل قبل الاستعادة.</p>`);$('#restore-version').onclick=()=>{d.versions.push({at:new Date().toISOString(),title:d.title,slides:copy(d.slides)});d.title=v.title;d.slides=copy(v.slides);d.updated=new Date().toISOString();persist();$('#modal').close();render();notify('استُعيد الإصدار إلى نسخة العمل مع الاحتفاظ بالنسخة السابقة.');};}
function paintScene(j,root=document){const stage=root.querySelector('.object-scene');if(!stage)return;stage.dataset.condition=j.condition;stage.querySelectorAll('[data-scene-object]').forEach(e=>{const p=sceneObjectPosition(j,e.dataset.sceneObject);e.style.left=p.x+'%';e.style.top=p.y+'%';});stage.querySelector('.scene-self')?.classList.toggle('current',['self','informed'].includes(j.condition));stage.querySelector('.scene-gift')?.classList.toggle('current',j.condition==='gift');const phase=root.querySelector('#scene-phase'),cause=root.querySelector('#scene-cause');if(phase)phase.textContent=j.condition==='self'?'١ · قبل الحكاية، لنفسك':j.condition==='informed'?'٢ · بعد الحكاية، لنفسك':j.condition==='gift'?'٣ · بعد الحكاية، هدية لصديق':'قبل الاختيار · الأشياء على الرف';if(cause)cause.textContent=sceneCause(j);}
function animateStory(j,root,onDone=()=>{}){clearInterval(animation);j.condition='equal';paintScene(j,root);if(matchMedia('(prefers-reduced-motion: reduce)').matches){j.condition='gift';paintScene(j,root);onDone();notify('عُرضت النتيجة بلا حركة. يمكنك تغيير المراحل يدويًا.');return;}const phases=['self',...(j.informed?['informed']:[]),'gift'];let phase=0;animation=setInterval(()=>{j.condition=phases[phase++];paintScene(j,root);const select=root.querySelector('#saved-scene-condition');if(select)select.value=j.condition;if(phase===phases.length){clearInterval(animation);onDone();}},2200);}
function animate(){animateStory(state.journey,document,()=>{paintVisual();persist();});}
function paintVisual(){paintScene(state.journey);if($('#visual-description'))$('#visual-description').textContent=visualText();}
function showSavedStory(d){const j=copy(d.original);j.condition='equal';modal(`<h2>اختياراك في مشهد واحد</h2><p>هذا مشهد من بيانات هذه المسودة الأصلية: الشيء الذي أخذته لنفسك، ثم هديتك للصديق. لا يغيّر نص المسودة ولا إصداراتها.</p><div class="story-visual">${objectScene(j)}</div><label for="saved-scene-condition">اختر مرحلة</label><select id="saved-scene-condition"><option value="equal">الأشياء على الرف</option><option value="self">اختياري لنفسي</option>${j.informed?'<option value="informed">اختياري بعد معرفة الحكاية</option>':''}<option value="gift">هديتي لصديق</option></select><div class="actions"><button id="saved-scene-play">شغّل المشهد المتحرك</button><button class="secondary" id="saved-scene-stop">إيقاف</button></div><p class="small muted">مشهد توضيحي مُعدّ للقصة، لا توليد فيديو من أي نص ولا تحليل للشخصية.</p>`);const root=$('#modal-body');$('#saved-scene-condition').onchange=e=>{clearInterval(animation);j.condition=e.target.value;paintScene(j,root);};$('#saved-scene-play').onclick=()=>animateStory(j,root,()=>{$('#saved-scene-condition').value=j.condition;});$('#saved-scene-stop').onclick=()=>{clearInterval(animation);$('#saved-scene-condition').value=j.condition;};$('#modal').addEventListener('close',()=>clearInterval(animation),{once:true});}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('التسجيل غير متاح في هذا المتصفح. يمكنك الكتابة بدلًا منه.');return;}const request=++micRequest;try{const acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(request!==micRequest||!$('#record-button')||document.hidden){acquired.getTracks().forEach(t=>t.stop());return;}micStream=acquired;micCancelled=false;micChunks=[];mic=new MediaRecorder(micStream);const recorder=mic,captureStream=micStream,chunks=[];mic.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};mic.onstop=()=>{captureStream.getTracks().forEach(t=>t.stop());if(mic!==recorder){chunks.length=0;return;}micStream=null;if(!micCancelled&&$('#record-playback')){if(micURL)URL.revokeObjectURL(micURL);micURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType||'audio/webm'}));$('#record-playback').innerHTML='<audio controls aria-label="استمع لتسجيلك المحلي"></audio>';$('#record-playback audio').src=micURL;$('#record-status').textContent='تسجيل مؤقت على هذا الجهاز. استمع واكتب ما تريد الاحتفاظ به. سيُحذف الصوت عند مغادرة هذه الخطوة.';}chunks.length=0;micChunks=[];};mic.start();$('#record-button').textContent='إيقاف التسجيل';$('#record-button').classList.add('recording');$('#cancel-record').hidden=false;$('#record-status').textContent='يجري التسجيل محليًا الآن. لا إرسال للصوت ولا تفريغ للنص.';}catch{micStream?.getTracks().forEach(t=>t.stop());micStream=null;notify('لم يُسمح بالميكروفون أو تعذر تشغيله. الكتابة متاحة دائمًا.');}}
function stopRecording(cancel){micRequest++;micCancelled=cancel;if(mic?.state==='recording')mic.stop();micStream?.getTracks().forEach(t=>t.stop());if($('#record-button')){$('#record-button').textContent='سجّل فكرتك بصوتك';$('#record-button').classList.remove('recording');$('#cancel-record').hidden=true;}if(cancel){if(micURL)URL.revokeObjectURL(micURL);micURL=null;if($('#record-playback'))$('#record-playback').innerHTML='';if($('#record-status'))$('#record-status').textContent='أُلغي التسجيل. لم يُحفظ الصوت ولم يُرسل.';}}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
$('#privacy').onclick=()=>{collectForm();modal(`<h2>بياناتك تحت يدك</h2><p>${embedded?'نسخة العمل في ذاكرة الصفحة مؤقتًا. اضغط «احفظ في المسودات» لحفظ التجربة كاملة في مساحة حسابك المشفّرة الحالية. لا تُحفظ بيانات الحساب كنص في تخزين المتصفح.':'هذه التجربة تحفظ التقدم والمسودات في هذا المتصفح فقط، وليست نسخة احتياطية مضمونة. قد تُفقد عند مسح بيانات المتصفح.'} التسجيلات الصوتية مؤقتة ولا تُرفع.</p><p>لا تحليل للشخصية، ولا تشغيل للوكيل أو خدمات مدفوعة. لا يُشارك شيء تلقائيًا.</p><div class="actions"><button id="export-all">تنزيل نسخة من بيانات التجربة</button>${corruptGuest?'<button class="secondary" id="export-raw">تنزيل البيانات السابقة كما هي</button>':''}<button class="secondary danger" id="reset-all">مسح بيانات هذه التجربة</button></div>${embedded?'<p class="small">الدخول وإدارة حسابك تبقى في الصفحة الأصلية.</p>':''}`);$('#export-all').onclick=()=>download('elhami-journeys-backup.json',JSON.stringify(state,null,2));if($('#export-raw')&&corruptGuest)$('#export-raw').onclick=()=>download('elhami-journeys-recovery.json',rawGuest||'');$('#reset-all').onclick=()=>{if(!confirm(embedded?'مسح تقدم هذه التجربة ومسوداتها وإصداراتها ومحتوى عالمي وذكرياتك وروابطك من مساحة حسابك المشفّرة؟ سيُزامن المسح. لا يشمل الحساب أو اللقاءات والمراجع القديمة. نزّل نسخة أولًا.':'مسح تقدم هذه التجربة ومسوداتها وأسئلتها ومحتوى عالمي وذكرياتك وروابطك من هذا الجهاز؟ لا يشمل الحساب أو المحتوى القديم. نزّل نسخة أولًا إن احتجتها.'))return;stopRecording(true);window.ElhamiContextWorkspace?.discardPending();corruptGuest=false;rawGuest=null;$('#storage-warning').hidden=true;state=defaults();persist();if(embedded)requestAccountSave();$('#modal').close();render();notify(embedded?'جارٍ حفظ مسح بيانات التجربة؛ لا يشمل المحتوى القديم.':'مُسحت بيانات هذه التجربة فقط.');};};
window.addEventListener('pagehide',()=>{stopRecording(true);clearInterval(animation);persist();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInterval(animation);stopRecording(false);}});
window.ElhamiJourney={run:act,getState:()=>copy(state),loadState:s=>{const valid=window.ElhamiJourneySchema.sanitize(s);if(!valid)throw Error('Invalid journey state');stopRecording(true);state={...defaults(),...valid};persist();render();},notify};
let bridgeGeneration=null,bridgeInitialized=!embedded,dirty=false,revision=0,accountSaving=false,savingRevision=0;window.elhamiMarkDirty=()=>{dirty=true;revision++;if(embedded&&bridgeInitialized)window.parent.postMessage({channel:'elhami-journey-v1',type:'dirty',generation:bridgeGeneration,dirty:true},location.origin);};
function requestAccountSave(){if(accountSaving){notify('يوجد حفظ جارٍ. احفظ التعديلات الجديدة بعد تأكيده.');return;}if(embedded&&bridgeInitialized){accountSaving=true;savingRevision=revision;window.parent.postMessage({channel:'elhami-journey-v1',type:'save',generation:bridgeGeneration,requestId:savingRevision,state:copy(state)},location.origin);}}
document.addEventListener('input',()=>{if(embedded&&state.view==='world'&&window.ElhamiContextWorkspace?.hasPendingEdits())window.elhamiMarkDirty();});document.addEventListener('change',()=>{if(embedded&&state.view==='world'&&window.ElhamiContextWorkspace?.hasPendingEdits())window.elhamiMarkDirty();});
window.addEventListener('message',e=>{if(!embedded||e.origin!==location.origin||e.source!==window.parent||e.data?.channel!=='elhami-journey-v1')return;const m=e.data;if(m.type==='init'){bridgeGeneration=m.generation;bridgeInitialized=true;const valid=window.ElhamiJourneySchema.sanitize(m.state);state=valid?{...defaults(),...valid}:defaults();render();dirty=false;}else if(m.generation!==bridgeGeneration)return;else if(m.type==='lock'){clearInterval(animation);stopRecording(true);state=defaults();$('#main').innerHTML='<p>المساحة مقفلة.</p>';bridgeInitialized=false;}else if(m.type==='pause'){stopRecording(true);clearInterval(animation);}else if(m.type==='save-result'){accountSaving=false;const pendingContext=!!window.ElhamiContextWorkspace?.hasPendingEdits();notify(m.ok&&pendingContext?'حُفظت البيانات المعتمدة. نموذج عالمي الجاري لم يُحفظ بعد؛ استخدم زر حفظه.':m.message);if(m.ok&&m.requestId===revision&&!pendingContext)dirty=false;if(pendingContext)dirty=true;window.parent.postMessage({channel:'elhami-journey-v1',type:'dirty',generation:bridgeGeneration,dirty},location.origin);}});
if(embedded){document.body.classList.add('embedded');$('.logo').parentElement.style.display='none';const saveProgress=document.createElement('button');saveProgress.className='quiet';saveProgress.textContent='حفظ التقدم';saveProgress.onclick=()=>{collectForm();requestAccountSave();notify('جارٍ حفظ التقدم…');};$('.site-header').append(saveProgress);$('#main').innerHTML='<p class="empty">جارٍ فتح تجربتك الخاصة…</p>';window.parent.postMessage({channel:'elhami-journey-v1',type:'ready'},location.origin);new ResizeObserver(()=>{window.parent.postMessage({channel:'elhami-journey-v1',type:'resize',generation:bridgeGeneration,height:Math.ceil(document.body.getBoundingClientRect().height)},location.origin);}).observe(document.body);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});}else {if(typeof URLSearchParams!=='undefined'){const entry=new URLSearchParams(location.search||'').get('path');if(['idea','reading','projects','group','world'].includes(entry))state.view=entry;}render();}if(corruptGuest){$('#storage-warning').hidden=false;$('#storage-warning').textContent='تعذر قراءة بيانات سابقة. لم نستبدلها. الحفظ متوقف؛ نزّل النسخة الأصلية من بياناتي قبل أي مسح.';}else if(!storageAvailable){$('#storage-warning').hidden=false;$('#storage-warning').textContent='تعذر قراءة التخزين المحلي. يمكنك التجربة وتنزيل بياناتك قبل المغادرة.';}
})();
